  const lines: string[] = []
  lines.push('# Serialization Performance Analysis')
  lines.push('')
  lines.push('**Serialization Score:** ' + r.serializationScore + '/100 | **Issues:** ' + r.totalIssues + ' | **Severity:** ' + r.severity.toUpperCase())
  lines.push('')
