  const lines: string[] = []
  lines.push('# Logging Discipline Analysis')
  lines.push('')
  lines.push('**Logging Score:** ' + r.loggingScore + '/100 | **Issues:** ' + r.totalIssues + ' | **Severity:** ' + r.severity.toUpperCase())
  lines.push('')
  lines.push('> ' + r.summary)
