  const lines: string[] = []
  lines.push('# CRDT State Sync Analysis')
  lines.push('')
  lines.push('**CRDT Score:** ' + r.crdtScore + '/100 | **Issues:** ' + r.totalIssues + ' | **Severity:** ' + r.severity.toUpperCase())
  lines.push('')
  lines.push('> ' + r.summary)
