  const lines: string[] = []
  lines.push('# Data Loader Optimization Analysis')
  lines.push('')
  lines.push('**Loader Score:** ' + r.loaderScore + '/100 | **Issues:** ' + r.totalIssues + ' | **Severity:** ' + r.severity.toUpperCase())
  lines.push('')
