  const lines: string[] = []
  lines.push('# Infrastructure Drift Analysis')
  lines.push('')
  lines.push('**Drift Score:** ' + r.driftScore + '/100 | **Issues:** ' + r.totalIssues + ' | **Severity:** ' + r.severity.toUpperCase())
  lines.push('')
