  const lines: string[] = []
  lines.push('# Semaphore Pattern Analysis')
  lines.push('')
  lines.push('**Semaphore Score:** ' + r.semaphoreScore + '/100 | **Issues:** ' + r.totalIssues + ' | **Severity:** ' + r.severity.toUpperCase())
  lines.push('')
  lines.push('> ' + r.summary)
