  const lines: string[] = []
  lines.push('# DNS Optimization Analysis')
  lines.push('')
  lines.push('**DNS Score:** ' + r.dnsScore + '/100 | **Issues:** ' + r.totalIssues + ' | **Severity:** ' + r.severity.toUpperCase())
