  const severity: Severity = storage.length > 0 ? 'warning' : totalIssues > 0 ? 'info' : 'info'

  return { totalIssues, severity, storage, network, hardeningScore,
    summary: storage.length + ' storage gap(s), ' + network.length + ' network gap(s)' }
